                        tmp23854 = tmp23781*tmp23776
                        tmp23855 = tmp23854*tmp23826
                        tmp23856 = 1.1283791670955126_wp*tmp23855
                        tmp23857 = tmp23853 + tmp23856
                        tmp23858 = -tmp23857
                        tmp23859 = tmp23848 + tmp23858
                        tmp23860 = tmp22793*tmp23859
                        tmp23861 = tmp23788*tmp23779
                        tmp23862 = tmp23781*tmp23851
                        tmp23863 = -tmp23862
                        tmp23864 = tmp23861 + tmp23863
                        tmp23865 = tmp23864*tmp22794
                        tmp22902 = tmp23860 + tmp23865
                     end if
                     tmp23866 = state%s36(i)*tmp22902
                     tmp22783 = tmp22783 + tmp23866
                  end if
               end block
            end do
            tmp22780(j) = tmp22780(j) + tmp22783
         end do
         !$omp end do
      end block
      !$omp end parallel
      call gemv(state%s17, tmp6260, tmp23867, trans="t")
      tmp23868 = tmp22780 + tmp23867
      hvp_vn = tmp22779 + tmp23868
   end subroutine nonlocal_pcm_tangent_one

   !> Nonlocal PCM (gaussian charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs nonlocal_pcm_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call nonlocal_pcm_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[nonlocal_pcm_response] call nonlocal_pcm_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call nonlocal_pcm_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                        hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine nonlocal_pcm_response

   !> One direction of nonlocal_pcm_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:), tmp15(:), tmp16(:), &
                               tmp17(:), tmp18(:), tmp19(:), tmp20(:), tmp21(:), tmp24(:), &
                               tmp25(:), tmp26(:), tmp27(:), tmp28(:), tmp29(:), tmp30(:), &
                               tmp31(:), tmp32(:), tmp33(:), tmp34(:), tmp35(:), tmp36(:), &
                               tmp37(:), tmp38(:)
      real(wp), allocatable :: tmp13(:), tmp14(:), tmp22(:), tmp23(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp33(npt), stat=stat)
      if (stat == 0) allocate (tmp34(npt), stat=stat)
      if (stat == 0) allocate (tmp35(npt), stat=stat)
      if (stat == 0) allocate (tmp36(npt), stat=stat)
      if (stat == 0) allocate (tmp37(npt), stat=stat)
      if (stat == 0) allocate (tmp38(npt), stat=stat)
      if (stat == 0) allocate (tmp13(3*npt), stat=stat)
      if (stat == 0) allocate (tmp14(3*npt), stat=stat)
      if (stat == 0) allocate (tmp22(3*npt), stat=stat)
      if (stat == 0) allocate (tmp23(3*npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[nonlocal_pcm_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s12
      state%op1%c2 => state%s13
      state%op1%c4 => state%s17
      state%op1%c6 => state%s19
      tmp1 = (-6.283185307179586_wp)*dv
      call gemv(state%s12, dv, tmp2)
      tmp3 = state%s21*tmp2
      tmp4 = tmp1 + tmp3
      call gemv(state%s17, dvn, tmp5)
      tmp6 = state%s23*tmp5
      tmp7 = tmp4 + tmp6
      call gemv(state%s13, dv, tmp8)
      tmp9 = tmp7 + tmp8
      call gemv(state%s19, dvn, tmp10)
      tmp11 = state%s25*tmp10
      tmp12 = tmp9 + tmp11
      tmp13(1:npt) = tmp12
      tmp13(npt + 1:2*npt) = 0.0_wp
      tmp13(2*npt + 1:3*npt) = 0.0_wp
      tmp14 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp13, tmp14, error)
      if (allocated(error)) return
      tmp15 = tmp14(npt + 1:2*npt)
      tmp16 = state%a*tmp15
      tmp17 = 0.039788735772973836_wp*tmp16
      tmp18 = (-0.039788735772973836_wp)*dvn
      tmp19 = tmp18*state%a
      tmp20 = 0.039788735772973836_wp*dv
      tmp21 = tmp20*state%a
      tmp22(1:npt) = tmp19
      tmp22(npt + 1:2*npt) = tmp21
      tmp22(2*npt + 1:3*npt) = 0.0_wp
      tmp23 = 0.0_wp
      call state%solver%solve(state%op1, .true., tmp22, tmp23, error)
      if (allocated(error)) return
      tmp24 = tmp23(1:npt)
      call gemv(state%s13, tmp24, tmp25, trans="t")
      tmp26 = tmp17 + tmp25
      tmp27 = state%s21*tmp24
      call gemv(state%s12, tmp27, tmp28, trans="t")
      tmp29 = tmp26 + tmp28
      tmp30 = (-6.283185307179586_wp)*tmp24
      hvp_v = tmp29 + tmp30
      tmp31 = tmp14(1:npt)
      tmp32 = state%a*tmp31
      tmp33 = (-0.039788735772973836_wp)*tmp32
      tmp34 = state%s25*tmp24
      call gemv(state%s19, tmp34, tmp35, trans="t")
      tmp36 = tmp33 + tmp35
      tmp37 = state%s23*tmp24
      call gemv(state%s17, tmp37, tmp38, trans="t")
      hvp_vn = tmp36 + tmp38
   end subroutine nonlocal_pcm_response_one

   !> Nonlocal PCM (gaussian charges): build the cavity operators
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] r  positions of the surface points
   !> @param[in] n  outward unit normals at the surface points
   !> @param[in] xi  gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
   !> @param[in] a  tessera areas, switched (ISWIG: F_i R_I^2 w_i)
   !> @param[out] error  error handling; allocated on failure
   !> @param[in] solver  linear solver, copied into the state; default dense LAPACK (Cholesky,
   !> symmetric or LU)
   subroutine nonlocal_pcm_mf_assemble(state, r, n, xi, a, error, solver)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Outward unit normals at the surface points
      real(wp), contiguous, intent(in) :: n(:, :)
      !> Gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
      real(wp), contiguous, intent(in) :: xi(:)
      !> Tessera areas, switched (ISWIG: F_i R_I^2 w_i)
      real(wp), contiguous, intent(in) :: a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error
      !> Linear solver
      class(pcm_solver), intent(in), optional :: solver

      integer :: npt
      integer :: stat

      stat = 0
      npt = size(r, 2)
      if (npt < 1) then
         call fatal_error(error, "[nonlocal_pcm_mf_assemble] empty discretization")
         return
      end if
      if (any(shape(r) /= [3, npt])) then
         call fatal_error(error, "[nonlocal_pcm_mf_assemble] r: wrong shape")
         return
      end if
      if (any(shape(n) /= [3, npt])) then
         call fatal_error(error, "[nonlocal_pcm_mf_assemble] n: wrong shape")
         return
      end if
      if (any(shape(xi) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_mf_assemble] xi: wrong shape")
         return
      end if
      if (any(shape(a) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_mf_assemble] a: wrong shape")
         return
      end if
      state%ready = 0
      if (allocated(state%solver)) deallocate (state%solver)
      if (allocated(state%a)) deallocate (state%a)
      if (allocated(state%xi)) deallocate (state%xi)
      if (allocated(state%r)) deallocate (state%r)
      if (allocated(state%n)) deallocate (state%n)
      if (allocated(state%v)) deallocate (state%v)
      if (allocated(state%s1)) deallocate (state%s1)
      if (allocated(state%s2)) deallocate (state%s2)
      if (allocated(state%s3)) deallocate (state%s3)
      if (allocated(state%s4)) deallocate (state%s4)
      if (allocated(state%s5)) deallocate (state%s5)
      if (allocated(state%s6)) deallocate (state%s6)
      if (allocated(state%s22)) deallocate (state%s22)
      if (allocated(state%vn)) deallocate (state%vn)
      if (allocated(state%s24)) deallocate (state%s24)
      if (allocated(state%s26)) deallocate (state%s26)
      if (allocated(state%s27)) deallocate (state%s27)
      if (allocated(state%s28)) deallocate (state%s28)
      if (allocated(state%s29)) deallocate (state%s29)
      if (allocated(state%s30)) deallocate (state%s30)
      if (allocated(state%s31)) deallocate (state%s31)
      if (allocated(state%s32)) deallocate (state%s32)
      if (allocated(state%s33)) deallocate (state%s33)
      if (allocated(state%s34)) deallocate (state%s34)
      if (allocated(state%s35)) deallocate (state%s35)
      if (allocated(state%s36)) deallocate (state%s36)
      if (allocated(state%s38)) deallocate (state%s38)
      if (allocated(state%s39)) deallocate (state%s39)
      if (allocated(state%s40)) deallocate (state%s40)
      if (allocated(state%s41)) deallocate (state%s41)
      if (allocated(state%s42)) deallocate (state%s42)
      if (allocated(state%s43)) deallocate (state%s43)
      if (allocated(state%s44)) deallocate (state%s44)
      if (allocated(state%s45)) deallocate (state%s45)
      if (allocated(state%s46)) deallocate (state%s46)
      if (allocated(state%s47)) deallocate (state%s47)
      if (allocated(state%s49)) deallocate (state%s49)
      if (allocated(state%s51)) deallocate (state%s51)
      if (allocated(state%s52)) deallocate (state%s52)
      if (allocated(state%s53)) deallocate (state%s53)
      if (allocated(state%s12)) deallocate (state%s12)
      if (allocated(state%s13)) deallocate (state%s13)
      if (allocated(state%s17)) deallocate (state%s17)
      if (allocated(state%s19)) deallocate (state%s19)
      state%npt = npt
      if (present(solver)) then
         allocate (state%solver, source=solver, stat=stat)
      else
         allocate (pcm_dense_solver :: state%solver, stat=stat)
      end if
      if (stat == 0) allocate (state%a(npt), stat=stat)
      if (stat == 0) allocate (state%xi(npt), stat=stat)
      if (stat == 0) allocate (state%r(3, npt), stat=stat)
      if (stat == 0) allocate (state%n(3, npt), stat=stat)
      if (stat == 0) allocate (state%v(npt), stat=stat)
      if (stat == 0) allocate (state%s1(npt), stat=stat)
      if (stat == 0) allocate (state%s2(npt), stat=stat)
      if (stat == 0) allocate (state%s3(npt), stat=stat)
      if (stat == 0) allocate (state%s4(npt), stat=stat)
      if (stat == 0) allocate (state%s5(npt), stat=stat)
      if (stat == 0) allocate (state%s6(npt), stat=stat)
      if (stat == 0) allocate (state%s22(npt), stat=stat)
      if (stat == 0) allocate (state%vn(npt), stat=stat)
      if (stat == 0) allocate (state%s24(npt), stat=stat)
      if (stat == 0) allocate (state%s26(npt), stat=stat)
      if (stat == 0) allocate (state%s27(npt), stat=stat)
      if (stat == 0) allocate (state%s28(npt), stat=stat)
      if (stat == 0) allocate (state%s29(npt), stat=stat)
      if (stat == 0) allocate (state%s30(npt), stat=stat)
      if (stat == 0) allocate (state%s31(npt), stat=stat)
      if (stat == 0) allocate (state%s32(3*npt), stat=stat)
      if (stat == 0) allocate (state%s33(npt), stat=stat)
      if (stat == 0) allocate (state%s34(npt), stat=stat)
      if (stat == 0) allocate (state%s35(npt), stat=stat)
      if (stat == 0) allocate (state%s36(npt), stat=stat)
      if (stat == 0) allocate (state%s38(npt), stat=stat)
      if (stat == 0) allocate (state%s39(npt), stat=stat)
      if (stat == 0) allocate (state%s40(npt), stat=stat)
      if (stat == 0) allocate (state%s41(npt), stat=stat)
      if (stat == 0) allocate (state%s42(npt), stat=stat)
      if (stat == 0) allocate (state%s43(npt), stat=stat)
      if (stat == 0) allocate (state%s44(npt), stat=stat)
      if (stat == 0) allocate (state%s45(npt), stat=stat)
      if (stat == 0) allocate (state%s46(npt), stat=stat)
      if (stat == 0) allocate (state%s47(npt), stat=stat)
      if (stat == 0) allocate (state%s49(npt), stat=stat)
      if (stat == 0) allocate (state%s51(npt), stat=stat)
      if (stat == 0) allocate (state%s52(npt), stat=stat)
      if (stat == 0) allocate (state%s53(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[nonlocal_pcm_mf_assemble] allocation failed")
         return
      end if
      state%s32 = 0.0_wp
      call state%solver%reset(nonlocal_pcm_n_operators)
      state%matrix_free = .true.

      state%a = a
      state%xi = xi
      state%r = r
      state%n = n
      state%s1 = state%r(1, :)
      state%s2 = state%r(2, :)
      state%s3 = state%r(3, :)
      state%s4 = state%n(1, :)
      state%s5 = state%n(2, :)
      state%s6 = state%n(3, :)

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine nonlocal_pcm_mf_assemble

   !> Nonlocal PCM (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs nonlocal_pcm_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[in] eps_inf  high-frequency permittivity of the solvent
   !> @param[in] lam  correlation length of the solvent polarization
   !> @param[in] eps_solute  relative permittivity inside the cavity
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_mf_medium(state, eps, eps_inf, lam, eps_solute, error)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> High-frequency permittivity of the solvent
      real(wp), intent(in) :: eps_inf
      !> Correlation length of the solvent polarization
      real(wp), intent(in) :: lam
      !> Relative permittivity inside the cavity
      real(wp), intent(in) :: eps_solute
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2, tmp3, tmp4

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[nonlocal_pcm_mf_medium] call nonlocal_pcm_assemble first")
         return
      end if
      state%ready = 1

      state%lam = lam
      state%eps_inf = eps_inf
      state%eps = eps
      state%eps_solute = eps_solute
      state%op2%npt = 3*npt
      state%op2%npoint = npt
      state%op2%id = 2
      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%xi => state%xi
      state%op2%a => state%a
      state%s7 = 1.0_wp/state%lam
      state%s8 = 1.0_wp/state%eps_inf
      state%s9 = state%s8*state%eps
      state%s10 = sqrt(state%s9)
      tmp1 = state%s7*state%s10
      state%s11 = tmp1**(2)
      state%op2%c1 = state%s11
      state%op2%c2 = state%s7
      state%op2%c3 = state%s10
      state%s14 = 1.0_wp/state%eps
      tmp2 = -state%s14
      state%s15 = state%s8 + tmp2
      state%s16 = state%eps_solute*state%s15
      state%op2%c4 = state%s16
      state%s18 = state%s8*state%eps_solute
      state%op2%c5 = state%s18
      state%s20 = state%s14*state%eps_inf
      state%op2%c6 = state%s20
      call state%solver%setup(state%op2, error)
      if (allocated(error)) return
      tmp3 = state%eps_solute*state%s14
      tmp4 = -tmp3
      state%s21 = 1.0_wp + tmp4
      state%s23 = -state%s16
      state%s25 = -state%s18

      state%ready = 2
   end subroutine nonlocal_pcm_mf_medium

   !> Nonlocal PCM (gaussian charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs nonlocal_pcm_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] u  interior potential trace, times 4 pi
